    try:
        test_alias_works()
        print("test_alias_works passed")
    except Exception as e:
        print(f"test_alias_works failed: {e}")

    try:
        test_name_works()
        print("test_name_works passed")
    except Exception as e:
        print(f"test_name_works failed: {e}")
